import json

# Find records that changed from unresolved to resolved
hist_records = {}
with open('logs/historical/pass_a/regrade.jsonl') as f:
    for line in f:
        r = json.loads(line)
        hist_records[r['record_id']] = r

new_records = {}
with open('/tmp/regrade_complete/regrade.jsonl') as f:
    for line in f:
        r = json.loads(line)
        new_records[r['record_id']] = r

changed = []
for rec_id in hist_records:
    if hist_records[rec_id]['label'] != new_records[rec_id]['label']:
        changed.append({
            'record_id': rec_id,
            'old': hist_records[rec_id]['label'],
            'new': new_records[rec_id]['label'],
            'reward_change': new_records[rec_id]['reward'] - hist_records[rec_id]['reward']
        })

print(f'Records with label changes: {len(changed)}')
print(f'  unresolved -> resolved: {sum(1 for c in changed if c[\"old\"] == \"unresolved\" and c[\"new\"] == \"resolved\")}')
print(f'  unresolved -> unscorable: {sum(1 for c in changed if c[\"old\"] == \"unresolved\" and c[\"new\"] == \"unscorable\")}')
print()
print('First 5 changed records:')
for c in changed[:5]:
    print(f'  {c[\"record_id\"][:50]:50s} {c[\"old\"]:12s} -> {c[\"new\"]:12s}')
"

