cd /workspace && python3 -c "
import json

hist = {}
with open('logs/historical/pass_a/regrade.jsonl') as f:
    for line in f:
        r = json.loads(line)
        hist[r['record_id']] = r

new = {}
with open('/tmp/regrade_complete/regrade.jsonl') as f:
    for line in f:
        r = json.loads(line)
        new[r['record_id']] = r

# Check if any resolved became unresolved
resolved_to_unresolved = []
for rec_id in hist:
    if hist[rec_id]['label'] == 'resolved' and new[rec_id]['label'] == 'unresolved':
        resolved_to_unresolved.append(rec_id)

print(f'Records that went from resolved to unresolved: {len(resolved_to_unresolved)}')
if resolved_to_unresolved:
    for rid in resolved_to_unresolved[:5]:
        print(f'  {rid}')
"

